window.STUDY_DATA.pitfalls = [{"id":"p-subnet","title":"子网边界地址算错","body":"网络地址不是「最小主机」，广播地址不是「最大主机」；可用主机数 = 2^主机位 − 2。","fix":"先写掩码二进制，按位与求网络地址，按位或求广播，再给可用范围。","point":"IP与子网","module":"major"},{"id":"p-opamp","title":"运放虚短虚断用错符号","body":"反相放大输出与输入反相，易漏负号；未判断饱和就套线性公式。","fix":"先确认线性区，再写 uo=−(Rf/R1)ui 或 (1+Rf/R1)ui，检查 |uo|≤电源。","point":"运算放大器","module":"major"},{"id":"p-loop","title":"循环边界与初值","body":"for(i=0;i<=n;i++) 多跑一趟；最值初值写成 0 导致负数序列全错。","fix":"最值初值取 a[0]；n 个元素用 i=0..n-1。","point":"循环与算法","module":"major"},{"id":"p-kvl","title":"回路绕行方向与电压正负","body":"参考方向约定后仍混乱标注升/降，方程整体差一符号。","fix":"固定顺时针绕行；与绕行同向取正，反向取负。","point":"直流电路分析","module":"major"},{"id":"p-ptr","title":"指针与数组混用出错","body":"把 p+2 理解成加 2 字节；*p++ 与 (*p)++ 混淆。","fix":"指针加整数按元素步长；不确定就拆成两步写。","point":"指针与数组","module":"major"},{"id":"p-limit","title":"等价无穷小乱用","body":"加减项里直接等价替换会算错极限。","fix":"乘除可等价；加减先通分/因式分解，或用泰勒/洛必达。","point":"极限与连续","module":"public"},{"id":"p-tense","title":"完成时与过去时混淆","body":"for/since 用过去时；yesterday/ago 用现在完成时。","fix":"for/since/so far → 完成时；具体过去时间点 → 一般过去时。","point":"时态与语态","module":"public"},{"id":"p-clause","title":"定语从句 that/which/who 误选","body":"先行词是人却用 which；介词提前后仍用 that。","fix":"先看先行词人/物；介词 + whom/which 时不能用 that。","point":"从句","module":"public"},{"id":"p-deriv","title":"复合函数求导漏链式","body":"sin(2x) 求导只写 cos2x，漏内层 2。","fix":"外层求导 × 内层求导；多层嵌套逐层相乘。","point":"导数与微分","module":"public"},{"id":"p-defint","title":"定积分上下限与绝对值","body":"曲线下方面积仍按积分正负，面积题漏绝对值。","fix":"面积用 ∫|f| 或分段；旋转体用 π∫f²。","point":"定积分","module":"public"}];
